#!/bin/sh
# Goal: Refactor build.js into separate files and pass MarkdownIt as an argument
# Plan:
# 1. Rename build.js to buildDoc.js
# 2. Create a new file, createMarkdownRenderer.js, that handles the creation of MarkdownIt
